head.b:skin:
/* 
THEME: Al-Mufassir Pro (Emerald & Gold)
SYSTEM: Deep Qur'anic Analytic Framework
*/
:root {
    --emerald-deep: #064e3b;
    --emerald-light: #065f46;
    --gold-leaf: #d4af37;
    --parchment: #fdfbf7;
    --text-dark: #1a2e25;
}
body {
    background-color: #f3f4f6;
    color: var(--text-dark);
    font-family: 'Amiri', 'Traditional Arabic', 'Inter', serif;
    margin: 0; padding: 0;
    background-image: radial-gradient(var(--emerald-light) 0.5px, transparent 0.5px);
    background-size: 30px 30px;
}
.header-wrap {
    background: var(--emerald-deep);
    color: var(--gold-leaf);
    padding: 60px 20px;
    text-align: center;
    border-bottom: 4px solid var(--gold-leaf);
    box-shadow: 0 4px 20px rgba(0,0,0,0.2);
}
.header-wrap h1 { 
    font-size: 32px; 
    font-weight: 900; 
    letter-spacing: 1px;
    margin: 0;
    text-transform: uppercase;
}
.main-container {
    max-width: 900px;
    margin: -30px auto 60px;
    padding: 20px;
}
.quran-card {
    background: var(--parchment);
    border-radius: 12px;
    padding: 45px;
    border: 1px solid var(--gold-leaf);
    box-shadow: 0 15px 35px rgba(0,0,0,0.1);
    position: relative;
}
.quran-card::before {
    content: "﷽";
    position: absolute;
    top: 20px; left: 50%;
    transform: translateX(-50%);
    font-size: 24px;
    color: var(--emerald-deep);
}

.input-group { margin-bottom: 25px; }
.input-group label {
    display: block;
    font-weight: 700;
    margin-bottom: 10px;
    color: var(--emerald-deep);
    font-size: 13px;
    text-transform: uppercase;
    border-right: 3px solid var(--gold-leaf);
    padding-right: 10px;
    text-align: right;
}
.input-group input, .input-group textarea, .input-group select {
    width: 100%;
    padding: 15px;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-family: inherit;
    box-sizing: border-box;
    background: #fff;
    font-size: 16px;
    color: var(--text-dark);
}
.input-group select { cursor: pointer; border-bottom: 3px solid var(--emerald-deep); }

.flex-row { display: flex; gap: 20px; flex-wrap: wrap; }
.flex-item { flex: 1; min-width: 280px; }

h2 { color: var(--emerald-deep); font-weight: 800; font-size: 20px; margin-bottom: 30px; text-align: center; }

.copy-btn {
    background: var(--emerald-deep);
    color: var(--gold-leaf);
    border: 2px solid var(--gold-leaf);
    padding: 20px;
    cursor: pointer;
    font-weight: 900;
    width: 100%;
    border-radius: 8px;
    transition: 0.3s;
    font-size: 16px;
    text-transform: uppercase;
    letter-spacing: 2px;
}
.copy-btn:hover { background: var(--gold-leaf); color: var(--emerald-deep); }
footer { text-align: center; color: var(--emerald-deep); padding: 40px; font-size: 12px; font-weight: bold; }

body.script:
function copyPrompt() {
    var verse = document.getElementById("inputVerse").value || "Al-Fatihah";
    var notes = document.getElementById("inputNotes").value || "Analisis umum dan tadabbur.";
    var method = document.getElementById("inputMethod").value;
    var depth = document.getElementById("inputDepth").value;

    var template = document.getElementById("templateID").innerText;

    var finalPrompt = template
        .replace("[USER_VERSE]", verse)
        .replace("[USER_NOTES]", notes)
        .replace(/\[USER_METHOD\]/g, method)
        .replace(/\[USER_DEPTH\]/g, depth);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("📖 Qur'anic Research Prompt Copied! [Verse: " + verse + "]");
}
